    email TEXT UNIQUE NOT NULL
)`);

app.get('/users', (req, res) => {
    db.all("SELECT * FROM users", [], (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows);
    });
});

app.post('/users', (req, res) => {
    const { name, email } = req.body;
    if (!name || !email) return res.status(400).json({ error: 'Nome e email são obrigatórios' });

    db.run("INSERT INTO users (name, email) VALUES (?, ?)", [name.trim(), email.trim()], function(err) {
        if (err) return res.status(409).json({ error: 'Email já cadastrado' });
        res.status(201).json({ id: this.lastID, name, email });
    });
});

app.delete('/users/:id', (req, res) => {
    db.run("DELETE FROM users WHERE id = ?", req.params.id, function(err) {
        if (err) return res.status(500).json({ error: err.message });
        if (this.changes === 0) return res.status(404).json({ error: 'Usuário não encontrado' });
        res.json({ success: true });
    });
});

app.listen(3000, () => console.log('Servidor rodando em http://localhost:3000'));
```

### `public/index.html`
```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <title>CRUD Básico</title>
    <style>
        body { font-family: sans-serif; max-width: 500px; margin: 40px auto; padding: 20px; }
        form { display: flex; gap: 10px; margin-bottom: 20px; }
        input { padding: 8px; flex: 1; }
        button { padding: 8px 12px; cursor: pointer; }
        ul { padding: 0; list-style: none; }
        li { display: flex; justify-content: space-between; background: #f4f4f4; padding: 8px; margin-bottom: 6px; align-items: center; }
    </style>
</head>
<body>
    <h2>Cadastro de Usuários</h2>
    <form id="userForm">
        <input type="text" id="name" placeholder="Nome" required>
        <input type="email" id="email" placeholder="E-mail" required>
        <button type="submit">Salvar</button>
    </form>
    <ul id="userList"></ul>

    <script>
        const api = '/users';
        const form = document.getElementById('userForm');
        const list = document.getElementById('userList');

        async function loadUsers() {
            const res = await fetch(api);
            const users = await res.json();
            list.innerHTML = '';
            users.forEach(u => {
                const li = document.createElement('li');
                li.textContent = `${u.name} (${u.email})`;
                const btn = document.createElement('button');
                btn.textContent = 'Excluir';
                btn.onclick = () => deleteUser(u.id);
                li.appendChild(btn);
                list.appendChild(li);
            });
        }

        form.onsubmit = async (e) => {
            e.preventDefault();
            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;

            const res = await fetch(api, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name, email })
            });

            if (res.ok) {
                form.reset();
                loadUsers();
            } else {
                const err = await res.json();
                alert(err.error || 'Erro ao salvar');
            }
        };

        async function deleteUser(id) {
            await fetch(`${api}/${id}`, { method: 'DELETE' });
            loadUsers();
        }

        loadUsers();
    </script>
</body>
</html>
